using System.Globalization;using System.Windows;using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using AutoPecasERP.Services.Oficina;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views;
public partial class EditarOsWindow:Window{readonly int _id;readonly Usuario _u;readonly ErpDbContext _db=new();OrdemServico? _os;public EditarOsWindow(int id,Usuario u){InitializeComponent();_id=id;_u=u;Loaded+=async(_,__)=>await Atualizar();}
async Task Atualizar(){_os=await _db.OrdensServico.Include(x=>x.Cliente).Include(x=>x.Veiculo).Include(x=>x.Itens).ThenInclude(x=>x.Produto).SingleAsync(x=>x.Id==_id);Titulo.Text=$"Ordem de Serviço {_os.Numero}";ClienteTxt.Text=_os.Cliente?.Nome??"";VeiculoTxt.Text=_os.Veiculo==null?"Sem veículo":$"{_os.Veiculo.Marca} {_os.Veiculo.Modelo} • {_os.Veiculo.Placa} • KM {_os.Km:N0}";StatusTxt.Text=_os.Status;TotalTxt.Text=$"Total: {_os.Total:C}";DiagnosticoBox.Text=_os.Diagnostico;PecasGrid.ItemsSource=_os.Itens.Where(x=>x.Tipo=="PECA").ToList();ServicosGrid.ItemsSource=_os.Itens.Where(x=>x.Tipo=="SERVICO").ToList();}
async void Peca_Click(object s,RoutedEventArgs e){if(_os?.Status=="FINALIZADA"){MessageBox.Show("OS finalizada.");return;}var q=BuscaProduto.Text.Trim();if(string.IsNullOrEmpty(q))return;var p=await _db.Produtos.FirstOrDefaultAsync(x=>x.CodigoInterno==q||x.CodigoBarras==q);if(p==null)p=await _db.Produtos.FirstOrDefaultAsync(x=>x.Descricao.Contains(q));if(p==null){MessageBox.Show("Produto não encontrado.");return;}if(!decimal.TryParse(QtdPeca.Text,NumberStyles.Number,CultureInfo.GetCultureInfo("pt-BR"),out var qtd)||qtd<=0){MessageBox.Show("Quantidade inválida.");return;}try{await new OficinaService(_db).AdicionarPecaAsync(_id,p.Id,qtd);BuscaProduto.Clear();await Atualizar();}catch(Exception ex){MessageBox.Show(ex.Message);}}
async void Servico_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(ServicoDesc.Text)){MessageBox.Show("Informe o serviço.");return;}decimal.TryParse(QtdServico.Text,NumberStyles.Number,CultureInfo.GetCultureInfo("pt-BR"),out var qtd);decimal.TryParse(ValorServico.Text,NumberStyles.Number,CultureInfo.GetCultureInfo("pt-BR"),out var valor);if(qtd<=0||valor<0){MessageBox.Show("Quantidade/valor inválido.");return;}await new OficinaService(_db).AdicionarServicoAsync(_id,ServicoDesc.Text,qtd,valor);ServicoDesc.Clear();ValorServico.Clear();await Atualizar();}
async void Salvar_Click(object s,RoutedEventArgs e){if(_os==null)return;_os.Diagnostico=DiagnosticoBox.Text;await _db.SaveChangesAsync();MessageBox.Show("Diagnóstico salvo.");}
async void Finalizar_Click(object s,RoutedEventArgs e){if(MessageBox.Show("Finalizar esta OS? As peças serão baixadas do estoque e o financeiro será gerado.","Confirmar",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;try{await new OficinaService(_db).FinalizarAsync(_id,_u.Nome);await Atualizar();MessageBox.Show("OS finalizada com sucesso.");}catch(Exception ex){MessageBox.Show(ex.Message);}}}